import React, { useEffect, useMemo } from 'react';
import { Form , Button, InputGroup} from 'react-bootstrap';
import Select from 'react-select';
import ImagePreview from '../components/ImagePreview';
import { useEmployeeAuth } from '../contexts/EmployeeAuthContext';

const EmailInternal = ({
    formData,
    handleChange,
    setFormData,
    isUploading,
    handleImageUpload,
    phmcGroupedOptions

}) => {
    const { staffName, isAdmin } = useEmployeeAuth();
    // Un email interne s'écrit EN SON NOM : l'expéditeur est imposé (un administrateur peut en choisir un autre).
    const myOption = useMemo(
        () => (phmcGroupedOptions || []).flatMap((group) => group.options)
            .find((option) => staffName && String(option.value || '').trim().toLowerCase() === String(staffName).trim().toLowerCase()) || null,
        [phmcGroupedOptions, staffName],
    );
    const lockedToMe = !!myOption && !isAdmin;
    useEffect(() => {
        if (lockedToMe && formData.phmcEmployee !== myOption.value) {
            setFormData((prev) => ({ ...prev, phmcEmployee: myOption.value, lastName: myOption.lastName || '' }));
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [lockedToMe, myOption, formData.phmcEmployee]);

    return (
        <>
        <p className="text-warning"><i className="fas fa-envelope me-1"></i>Ce formulaire est <strong>remplacé par la Messagerie interne</strong> de la boîte à outils (destinataire choisi dans l'annuaire, aperçu, PDF, image, copie du titre et du BBCode, notification). Cet écran ne sert plus qu'à consulter ou exporter un ancien rapport.</p>
        <Form.Label className="form-section-title">Destinataire et objet</Form.Label>
        <div style={{ display: 'flex', gap: '10px' }}>
            <Form.Control
                type="text"
                name="internalEmailSubject"
                value={formData.internalEmailSubject || ''}
                onChange={handleChange}
                placeholder="Sujet de l'email"
                className="form-control"

            />
            <Form.Control
                type="text"
                name="internalEmailRecipient"
                value={formData.internalEmailRecipient || ''}
                onChange={handleChange}
                placeholder="Destinataire de l'email"
                className="form-control"

            />
        </div>
        <Form.Label className="form-section-title">Message</Form.Label>
        <div style={{ display: 'flex', gap: '10px' }}>
            <Form.Control
            as="textarea"
            name="internalEmailBody"
            value={formData.internalEmailBody || ''}
            onChange={handleChange}
            rows="4"
            placeholder="Corps de l'email"
            className="form-control"
        />
        </div>
        <Form.Label className="form-section-title">Signature</Form.Label>
        <Form.Group className="mb-3 upload-container">
        <InputGroup>
            <Form.Control
                as="textarea"
                rows="4"
                name="internalEmailSignatureImage"
                value={formData.internalEmailSignatureImage || ''}
                onChange={handleChange}
                className="form-control"
                placeholder="Image de signature de l'employé"
                onPaste={(e) => {
                    const clipboardData = e.clipboardData || window.clipboardData;
                    const pastedData = clipboardData.getData('text');
                    const items = clipboardData.items;


                    let hasImageItem = false;

                    // Check if pasted content is a URL
                    const urlRegex = /(https?:\/\/[^\s]+)/g;
                    const containsUrl = urlRegex.test(pastedData);


                    // Handle image files from clipboard
                    for (let i = 0; i < items.length; i++) {
                        if (items[i].type.indexOf('image') !== -1) {
                            hasImageItem = true;
                            const file = items[i].getAsFile();
                            handleImageUpload({ target: { files: [file] } }, 'internalEmailSignatureImage');
                            e.preventDefault();
                            break;
                        }
                    }

                    // If it's a URL and not an image file, allow direct paste
                    if (containsUrl && !hasImageItem) {

                        // Get current value and cursor position
                        const currentValue = formData.internalEmailSignatureImage || '';
                        const cursorPos = e.target.selectionStart;


                        // Add comma if there's existing content
                        const separator = currentValue && currentValue.trim().length > 0 ? ', ' : '';
                        const newValue = currentValue.slice(0, cursorPos) +
                            (cursorPos > 0 ? separator : '') +
                            pastedData +
                            currentValue.slice(cursorPos);


                        // Update form data
                        setFormData(prev => ({
                            ...prev,
                            internalEmailSignatureImage: newValue
                        }));

                        e.preventDefault();
                    } else {
                    }
                }}
            />
            <Button
                variant="success"
                disabled={isUploading}
                onClick={() => {
                    const input = document.createElement('input');
                    input.type = 'file';
                    input.accept = 'image/*';
                    input.multiple = true;
                    input.onchange = (e) => handleImageUpload(e, 'internalEmailSignatureImage');
                    input.click();
                }}
            >
                <i className={`fas ${isUploading ? 'fa-spinner fa-spin' : 'fa-upload'}`}></i>
                {isUploading ? 'Téléchargement...' : 'Télécharger images'}
            </Button>

        </InputGroup>
        <span className="helper-text">
            Télécharger l'image de signature. Prend en charge le collage depuis le presse-papiers (Ctrl+V). Hébergé par ImgBB.
        </span>
        <ImagePreview imageUrls={formData.internalEmailSignatureImage} />
    </Form.Group>

        <Form.Label className="form-section-title">Expéditeur</Form.Label>
        <Select
        name="phmcEmployee"
        value={phmcGroupedOptions
            .flatMap(group => group.options)
            .find(option => option.value === formData.phmcEmployee) || null}
        onChange={(selectedOption) => {
            // eslint-disable-next-line no-unused-vars
            const lastName = selectedOption ? selectedOption.lastName : '';
            setFormData(prev => ({
                ...prev,
                phmcEmployee: selectedOption ? selectedOption.value : '',
                lastName: selectedOption ? selectedOption.lastName : '' // Use lastName from the selected option
            }));
        }}
        options={phmcGroupedOptions}
        isClearable={!lockedToMe}
        isDisabled={lockedToMe}
        placeholder="Sélectionner un médecin. (Vous pouvez taper pour rechercher!)"
        className="form-control"
        styles={{
            control: (base) => ({
                ...base,
                backgroundColor: '#16202c',
                color: '#eeeeeeb0',
                borderColor: '#30363d',
                '&:hover': {
                    borderColor: '#30363d'
                }
            }),
            menu: (base) => ({
                ...base,
                backgroundColor: '#16202c',
                zIndex: 1000
            }),
            option: (base, state) => ({
                ...base,
                backgroundColor: state.isFocused ? 'Grey' : '#16202c',
                color: '#eeeeeeb0'
            }),
            singleValue: (base) => ({
                ...base,
                color: '#eeeeeeb0'
            }),
            input: (base) => ({
                ...base,
                color: '#eeeeeeb0'
            }),
            placeholder: (base) => ({
                ...base,
                color: '#eeeeeeb0'
            })
        }}
    />
    <Form.Label></Form.Label>
    <div style={{ display: 'flex', gap: '10px' }}>
            <Form.Control
                type="text"
                name="internalEmailSenderTitle"
                value={formData.internalEmailSenderTitle || ''}
                onChange={handleChange}
                placeholder="Fonction au sein du PHMC"
                className="form-control"

            />
            <Form.Control
                type="text"
                name="internalEmailSenderDepartment"
                value={formData.internalEmailSenderDepartment || ''}
                onChange={handleChange}
                placeholder="Département assigné"
                className="form-control"

            />
        </div>
        </>
);
};

export default EmailInternal;
